"""Print palm height / grab / pinch stats. usage: leap_probe.py SECONDS [label]"""
import sys, time, statistics as st
import leap
secs = float(sys.argv[1]); label = sys.argv[2] if len(sys.argv) > 2 else ""
rows = []; info = {"conn": False, "dev": 0, "frames": 0}
class L(leap.Listener):
    def on_connection_event(self, e): info["conn"] = True
    def on_device_event(self, e): info["dev"] += 1
    def on_tracking_event(self, e):
        info["frames"] += 1
        if e.hands:
            h = e.hands[0]
            rows.append((time.time(), h.palm.position.y, h.grab_strength, h.pinch_strength,
                         getattr(h, "pinch_distance", 0.0), str(h.type), len(e.hands)))
c = leap.Connection(); c.add_listener(L())
with c.open():
    t0 = time.time(); nxt = 1.0
    while time.time() - t0 < secs:
        time.sleep(0.05)
        if time.time() - t0 >= nxt and "-v" in sys.argv:
            nxt += 1.0
            r = [x for x in rows if x[0] > time.time() - 1.0]
            if r: print(f"  t={nxt-1:4.0f}s y={st.mean(x[1] for x in r):6.0f}mm grab={st.mean(x[2] for x in r):.2f} pinch={st.mean(x[3] for x in r):.2f} pdist={st.mean(x[4] for x in r):5.1f}")
            else: print(f"  t={nxt-1:4.0f}s no hand")
print(label, info, "hand frames", len(rows))
if rows:
    for name, i in (("y_mm", 1), ("grab", 2), ("pinch", 3), ("pinch_dist", 4)):
        v = sorted(x[i] for x in rows); q = lambda p: v[min(len(v)-1, int(p*len(v)))]
        print(f"  {name:10s} min {v[0]:7.2f}  p5 {q(.05):7.2f}  p50 {q(.5):7.2f}  p95 {q(.95):7.2f}  max {v[-1]:7.2f}")
EOF
.venv/bin/python $S/leap_probe.py 4 baseline

